#!/usr/bin/env bash\nset -euo pipefail\n\n# Mock rationale: Use local null provider; no external calls.\n\n# Initialize Terraform\nterraform init -backend=false > /dev/null\n\n# Validate configuration\nterraform validate\n\n# Run a plan with example variables\ncat > terraform.tfvars <<EOF\ndestination     = "Mars"\nactivation_time = "2026-07-01T00:00:00Z"\nEOF\n\nPLAN_OUTPUT=$(terraform plan -var-file=terraform.tfvars -no-color)\n\n# Check that the plan contains the expected portal URL output\nif ! echo "$PLAN_OUTPUT" | grep -q "https://void.example.com/portal?dest=Mars&time=2026-07-01T00:00:00Z"; then\n  echo "Expected portal URL not found in plan output"\n  exit 1\nfi\n\necho "All tests passed."\n
